CREATE OR REPLACE VIEW `UeserType_mobile_fill_Daily_transfer_preparer_locukupEdit` AS select a.id,a.Name_type  from UeserType_mobile as a 
EXCEPT
select a.ueserTyp,b.Name_type from Daily_transfer_preparer_schedule as a 
