CREATE OR REPLACE VIEW `View_CBranch` AS SELECT ID AS FBranchID,CASE WHEN IsMain=1 then 50.000 WHEN BranchType=1 AND IsMain=0 THEN 33.000 WHEN BranchType=3 THEN 50.00 END AS FBRate,ID AS SBranchID,CASE WHEN IsMain=1 then 50.000 WHEN BranchType=1 AND IsMain=0 THEN 33.000 WHEN BranchType=3 THEN 0 END AS SBRate FROM CoBranch;

CREATE OR REPLACE VIEW `View_SHOWBRANCHSCREENS_ROLE` AS SELECT A.ScreenID, A.CanShow, A.CanOpen, A.CanAdd, A.CanEdit, A.CanDelete, A.CanPrint, E.CanShow AS IsShow, E.RPID, A.ID, A.ProfileID, C.ID AS Expr1, B.USID, B.UName, B.USettingProfileID, 
                         D.ID AS Expr2
FROM            UserAccessProfileDetails AS A LEFT OUTER JOIN
                         TB_Users AS B ON A.ProfileID = B.USettingProfileID LEFT OUTER JOIN
                         UserAccessProfileName AS C ON A.ProfileID = C.ID LEFT OUTER JOIN
                         MainTabTb AS D ON A.ScreenID = D.ID LEFT OUTER JOIN
                         RibbonPermission AS E ON C.ID = E.ProfileID;

CREATE OR REPLACE VIEW `VW_AccountBalances` AS SELECT
    AccIDFrom AS AccID,
    CurrencyID,
    SUM(IFNULL(Credit,0) - IFNULL(Debit,0)) AS Balance
FROM ExSyAccountsCurrency_AccSafeActivityTb
WHERE IsActive = 1
GROUP BY
    AccIDFrom,
    CurrencyID;

CREATE OR REPLACE VIEW `vw_SalaryCalc` AS SELECT        ROW_NUMBER() OVER (ORDER BY ID ASC) AS '#', ID,BranchID, EMPNAME AS 'اسم الموظف', SalaryVal AS 'قيمة الراتب', BonusVal AS 'إجمالي العلاوات', 
SalaryVal + BonusVal AS 'الإجمالي الكلي'
FROM            EmployeeTb;

CREATE OR REPLACE VIEW `VW_SALARYCALCLAST` AS SELECT
          A.ID,
          A.AccID,
          A.EMPNAME                               AS `اسم الموظف`,
          D.BName                                 AS الفرع,
          IFNULL(A.SalaryVal, 0.000)              AS `الراتب الأساسي`,
          EMP_GetConstanceIncreaseToals(A.ID) AS `علاوات ثابتة`,
          EMP_GetTempIncreaseToals(A.ID)      AS `علاوات أخرى`,
          EMP_GetDiscTtoals(A.ID)             AS `خصميات متنوعة`,
          EMP_GetLeaveDiscountTotal(A.ID)     AS `خصم إجازة`,
          EMP_GetADVPMNTTtoals(A.ID)          AS `خصم السلفة`,
          EMP_GetADVPMNTTtoalsIndivdual(A.ID) AS `باقي السلفة`,
          EMP_GetNettoals(A.ID)               AS الصافي,
          A.BranchID,         
          A.PHONE1                                AS `رقم هاتف الموظف`,
          A.CODE                                  AS `الرقمي الوظيفي`,
          A.EMPDATE,
          a.BankSalaryCalc,
          A.ISACTIVE,
          a.ID AS EMPID,
          c.ECNAME  AS التصنيف
  FROM
          EmployeeTb AS A
      LEFT OUTER JOIN
        CoBranch AS D
          ON A.BranchID = D.ID
         LEFT JOIN
         EmployeeClassificationTb  c
         ON a.CLASSIFICATION=c.ID

  WHERE
          (A.ISACTIVE = 1);

